css:
#tongsci1-3-3-4-flower .fl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #fbf6ee; }
#tongsci1-3-3-4-flower .fl-stage canvas { touch-action: none; cursor: pointer; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-4-flower .fl-tray .now-chip { position: static; font-size: 19px; padding: 6px 14px; flex: 1 1 auto; min-width: 0; }
#tongsci1-3-3-4-flower .fl-panel { gap: 12px; }
#tongsci1-3-3-4-flower .fl-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 6.2em; flex: none; }
#tongsci1-3-3-4-flower .fl-out b { color: var(--accent); }
#tongsci1-3-3-4-flower .fl-def { margin: 0; display: grid; gap: 8px; flex: none; }
#tongsci1-3-3-4-flower .fl-def div { border-left: 6px solid #2a7fc0; background: color-mix(in srgb, #2a7fc0 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 6px 14px; }
#tongsci1-3-3-4-flower .fl-def dt { font: 800 19px var(--f-body); color: #1d5f94; }
#tongsci1-3-3-4-flower .fl-def dd { margin: 2px 0 0; font-size: 17px; line-height: 1.45; }
#tongsci1-3-3-4-flower .fl-photo { margin: 0; flex: none; border: 2px solid var(--ink); border-radius: 10px; overflow: hidden; background: #fff; }
#tongsci1-3-3-4-flower .fl-photo[hidden] { display: none; }
#tongsci1-3-3-4-flower .fl-photo img { display: block; width: 100%; height: 150px; object-fit: cover; }
#tongsci1-3-3-4-flower .fl-photo figcaption { background: var(--paper-2); font: 600 15px/1.3 var(--f-body); padding: 4px 10px; color: var(--ink-2); }
#tongsci1-3-3-4-flower .fl-photo figcaption span { font-weight: 800; color: var(--accent); margin-right: 6px; }
#tongsci1-3-3-4-flower .fl-photo figcaption small { display: block; font-size: 12px; color: var(--ink-3); }
section#tongsci1-3-3-4-flower.ex.u-done .fl-def { display: none; }

